{
  "rules": [
    {
      "id": "check_ounces",
      "description": "Ensure that the 'ounces' column contains numeric values within a reasonable range.",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeBetween(column='ounces', min_value=0.5, max_value=12)",
      "evidence_references": ["https://www.brewersassociation.org/education-and-resources/beer-101/beer-basics/beer-volume/"]
    },
    {
      "id": "check_abv",
      "description": "Ensure that the 'abv' column contains numeric values within a reasonable range.",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeBetween(column='abv', min_value=3, max_value=15)",
      "evidence_references": ["https://www.brewersassociation.org/education-and-resources/beer-101/beer-basics/beer-alcohol-content/"]
    },
    {
      "id": "checkibu",
      "description": "Ensure that the 'ibu' column contains numeric values within a reasonable range.",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeBetween(column='ibu', min_value=0, max_value=100)",
      "evidence_references": ["https://www.brewersassociation.org/education-and-resources/beer-101/beer-basics/beer-bitterness/"]
    },
    {
      "id": "check_unique_brewery_names",
      "description": "Ensure that the 'brewery_name' column contains unique values.",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeUnique(column='brewery_name')",
      "evidence_references": ["https://www.brewersassociation.org/education-and-resources/beer-101/beer-basics/beer-breweries/"]
    }
  ],
  "abstentions": [
    "The 'source_documentation' does not specify any constraints on the format of the 'id', 'beer_name', 'style', 'city', and 'state' columns, so these columns are not checked."
  ]
}
